  7	import com.pousadamarealta.api.controller.ReportController;
  8	import com.pousadamarealta.api.controller.ReservationController;
  9	import com.pousadamarealta.api.controller.RoomController;
 10	import com.pousadamarealta.api.dto.ErrorResponse;
 11	import com.pousadamarealta.notification.FinanceNotifier;
 12	import com.pousadamarealta.notification.GuestNotifier;
 13	import com.pousadamarealta.notification.HousekeepingNotifier;
 14	import com.pousadamarealta.notification.NotificationService;
 15	import com.pousadamarealta.notification.ReservationObserver;
 16	import com.pousadamarealta.repository.*;
 17	import com.zaxxer.hikari.HikariConfig;
 18	import com.zaxxer.hikari.HikariDataSource;
 19	import io.javalin.Javalin;
 20	import io.javalin.json.JsonMapper;
 21	
 22	import javax.sql.DataSource;
 23	import java.lang.reflect.Type;
 24	import java.util.List;
 25	
 26	public class App {
 27	
 28	    public static void main(String[] args) {
 29	        DataSource dataSource = createDataSource();
 30	
 31	        DatabaseInitializer dbInitializer = new DatabaseInitializer(dataSource);
 32	        dbInitializer.initialize();
 33	
 34	        RoomRepository roomRepository = new RoomRepository(dataSource);
 35	        roomRepository.initializeRooms();
 36	
 37	        MessageRepository messageRepository = new MessageRepository(dataSource);
 38	        NotificationService notificationService = new NotificationService(messageRepository);
 39	
 40	        List<ReservationObserver> observers = List.of(
 41	            new GuestNotifier(notificationService),
 42	            new HousekeepingNotifier(notificationService),
 43	            new FinanceNotifier(notificationService)
 44	        );
 45	
 46	        ReservationRepository reservationRepository = new ReservationRepository(dataSource, observers);
 47	
 48	        RoomController roomController = new RoomController(roomRepository);
 49	        ReservationController reservationController = new ReservationController(
 50	            roomRepository, reservationRepository, observers
 51	        );
 52	        MessageController messageController = new MessageController(messageRepository);
 53	        ReportController reportController = new ReportController(roomRepository, reservationRepository);
 54	
 55	        int port = getPort();
 56	
 57	        Javalin app = Javalin.create(config -> {
 58	            config.jsonMapper(createJsonMapper());
 59	        });
 60	
 61	        app.exception(ApiException.class, (e, ctx) -> {
 62	            ctx.status(e.getStatusCode())
 63	               .json(new ErrorResponse(e.getErrorCode(), e.getMessage()));
 64	        });
 65	
 66	        app.exception(Exception.class, (e, ctx) -> {
 67	            e.printStackTrace();
 68	            ctx.status(500)
 69	               .json(new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
 70	        });
 71	
 72	        app.get("/rooms", roomController::getRooms);
 73	
 74	        app.post("/reservations", reservationController::createReservation);
 75	        app.get("/reservations/{id}", reservationController::getReservation);
 76	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 77	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 78	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 79	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 80	        app.get("/reservations/{id}/document", reservationController::getDocument);
 81	
 82	        app.get("/messages", messageController::getMessages);
 83	
 84	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 85	        app.get("/reports/revenue", reportController::getRevenueReport);
 86	
 87	        app.start(port);
 88	
 89	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 90	        System.out.println("Servidor rodando na porta " + port);
 91	    }
 92	
 93	    private static DataSource createDataSource() {
 94	        String url = System.getenv("DB_URL");
 95	        String user = System.getenv("DB_USER");
 96	        String password = System.getenv("DB_PASSWORD");
 97	
 98	        if (url == null) {
 99	            url = "jdbc:postgresql://localhost:5432/pousada";
100	        }
101	        if (user == null) {
102	            user = "postgres";
103	        }
104	        if (password == null) {
105	            password = "postgres";
106	        }
107	
108	        HikariConfig config = new HikariConfig();
109	        config.setJdbcUrl(url);
110	        config.setUsername(user);
111	        config.setPassword(password);
112	        config.setMaximumPoolSize(10);
113	
114	        return new HikariDataSource(config);
115	    }
116	
117	    private static int getPort() {
118	        String portEnv = System.getenv("PORT");
119	        if (portEnv != null && !portEnv.isBlank()) {
120	            try {
121	                return Integer.parseInt(portEnv);
122	            } catch (NumberFormatException e) {
123	                System.err.println("Invalid PORT value, using default 7070");
124	            }
125	        }
126	        return 7070;
127	    }
128	
129	    private static JsonMapper createJsonMapper() {
130	        Gson gson = new GsonBuilder()
131	            .setPrettyPrinting()
132	            .create();
133	
134	        return new JsonMapper() {
135	            @Override
136	            public <T> T fromJsonString(String json, Type targetType) {
137	                return gson.fromJson(json, targetType);
138	            }
139	
140	            @Override
141	            public String toJsonString(Object obj, Type type) {
142	                return gson.toJson(obj, type);
143	            }
144	        };
145	    }
146	}
