167	package com.pousadamarealta.api.controller;
168	
169	import com.pousadamarealta.api.ApiException;
170	import com.pousadamarealta.api.dto.CreateReservationRequest;
171	import com.pousadamarealta.api.dto.DocumentResponse;
172	import com.pousadamarealta.api.dto.ReservationResponse;
173	import com.pousadamarealta.domain.*;
174	import com.pousadamarealta.notification.ReservationObserver;
175	import com.pousadamarealta.repository.ReservationRepository;
176	import com.pousadamarealta.repository.RoomRepository;
177	import io.javalin.http.Context;
178	
179	import java.time.LocalDate;
180	import java.time.format.DateTimeFormatter;
181	import java.time.format.DateTimeParseException;
182	import java.util.List;
183	
184	public class ReservationController {
185	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE;
186	
187	    private final RoomRepository roomRepository;
188	    private final ReservationRepository reservationRepository;
189	    private final List<ReservationObserver> observers;
190	
191	    public ReservationController(
192	        RoomRepository roomRepository,
193	        ReservationRepository reservationRepository,
194	        List<ReservationObserver> observers
195	    ) {
196	        this.roomRepository = roomRepository;
197	        this.reservationRepository = reservationRepository;
198	        this.observers = observers;
199	    }
200	
201	    public void createReservation(Context ctx) {
202	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
203	
204	        validateRequest(request);
205	
206	        Room room = roomRepository.findByNumber(request.roomNumber())
207	            .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Room not found"));
208	
209	        LocalDate checkIn = parseDate(request.checkIn());
210	        LocalDate checkOut = parseDate(request.checkOut());
211	
212	        if (!checkOut.isAfter(checkIn)) {
213	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
214	        }
215	
216	        if (request.guests() < 1) {
217	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
218	        }
219	
220	        if (request.guests() > room.getCapacity()) {
221	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Number of guests exceeds room capacity");
222	        }
223	
224	        RatePlan ratePlan;
225	        try {
226	            ratePlan = RatePlan.valueOf(request.ratePlan());
227	        } catch (IllegalArgumentException e) {
228	            throw new ApiException(400, "INVALID_REQUEST", "Invalid rate plan");
229	        }
230	
231	        List<Reservation> conflicting = reservationRepository.findByRoomAndDateRange(
232	            request.roomNumber(), checkIn, checkOut
233	        );
234	
235	        if (!conflicting.isEmpty()) {
236	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for the selected dates");
237	        }
238	
239	        Reservation reservation = new Reservation(
240	            request.roomNumber(),
241	            room.getType(),
242	            request.guestName(),
243	            request.guestEmail(),
244	            request.guestCpf(),
245	            checkIn,
246	            checkOut,
247	            request.guests(),
248	            ratePlan
249	        );
250	
251	        for (ReservationObserver observer : observers) {
252	            reservation.addObserver(observer);
253	        }
254	
255	        reservationRepository.save(reservation);
256	
257	        ctx.status(201).json(ReservationResponse.from(reservation));
258	    }
259	
260	    public void getReservation(Context ctx) {
261	        long id = parseLongPathParam(ctx, "id");
262	
263	        Reservation reservation = reservationRepository.findById(id)
264	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
265	
266	        ctx.json(ReservationResponse.from(reservation));
267	    }
268	
269	    public void confirmReservation(Context ctx) {
270	        long id = parseLongPathParam(ctx, "id");
271	
272	        Reservation reservation = reservationRepository.findById(id)
273	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
274	
275	        try {
276	            reservation.confirm();
277	            reservationRepository.save(reservation);
278	        } catch (IllegalStateException e) {
279	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
280	        }
281	
282	        ctx.json(ReservationResponse.from(reservation));
283	    }
284	
285	    public void cancelReservation(Context ctx) {
286	        long id = parseLongPathParam(ctx, "id");
287	
288	        Reservation reservation = reservationRepository.findById(id)
289	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
290	
291	        try {
292	            reservation.cancel();
293	            reservationRepository.save(reservation);
294	        } catch (IllegalStateException e) {
295	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
296	        }
297	
298	        ctx.json(ReservationResponse.from(reservation));
299	    }
300	
301	    public void checkIn(Context ctx) {
302	        long id = parseLongPathParam(ctx, "id");
303	
304	        Reservation reservation = reservationRepository.findById(id)
305	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
306	
307	        try {
308	            reservation.checkIn();
309	            reservationRepository.save(reservation);
310	        } catch (IllegalStateException e) {
311	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
312	        }
313	
314	        ctx.json(ReservationResponse.from(reservation));
315	    }
316	
317	    public void checkOut(Context ctx) {
318	        long id = parseLongPathParam(ctx, "id");
319	
320	        Reservation reservation = reservationRepository.findById(id)
321	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
322	
323	        try {
324	            reservation.checkOut();
325	            reservationRepository.save(reservation);
326	        } catch (IllegalStateException e) {
327	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", e.getMessage());
328	        }
329	
330	        ReservationDocument document = new ReservationDocument(reservation);
331	        ctx.json(DocumentResponse.from(document));
332	    }
333	
334	    public void getDocument(Context ctx) {
335	        long id = parseLongPathParam(ctx, "id");
336	
337	        Reservation reservation = reservationRepository.findById(id)
338	            .orElseThrow(() -> new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found"));
339	
340	        if (reservation.getStatus() == ReservationStatus.PENDING ||
341	            reservation.getStatus() == ReservationStatus.CANCELLED) {
342	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Document is only available for paid reservations");
343	        }
344	
345	        ReservationDocument document = new ReservationDocument(reservation);
346	        ctx.json(DocumentResponse.from(document));
347	    }
348	
349	    private void validateRequest(CreateReservationRequest request) {
350	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
351	            throw new ApiException(400, "INVALID_REQUEST", "Room number is required");
352	        }
353	        if (request.guestName() == null || request.guestName().isBlank()) {
354	            throw new ApiException(400, "INVALID_REQUEST", "Guest name is required");
355	        }
356	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
357	            throw new ApiException(400, "INVALID_REQUEST", "Guest email is required");
358	        }
359	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
360	            throw new ApiException(400, "INVALID_REQUEST", "Guest CPF is required");
361	        }
362	        if (request.checkIn() == null || request.checkIn().isBlank()) {
363	            throw new ApiException(400, "INVALID_REQUEST", "Check-in date is required");
364	        }
365	        if (request.checkOut() == null || request.checkOut().isBlank()) {
366	            throw new ApiException(400, "INVALID_REQUEST", "Check-out date is required");
367	        }
368	        if (request.guests() == null) {
369	            throw new ApiException(400, "INVALID_REQUEST", "Number of guests is required");
370	        }
371	        if (request.ratePlan() == null || request.ratePlan().isBlank()) {
372	            throw new ApiException(400, "INVALID_REQUEST", "Rate plan is required");
373	        }
374	    }
375	
376	    private LocalDate parseDate(String date) {
377	        try {
378	            return LocalDate.parse(date, DATE_FORMAT);
379	        } catch (DateTimeParseException e) {
380	            throw new ApiException(400, "INVALID_REQUEST", "Invalid date format, expected yyyy-MM-dd");
381	        }
382	    }
383	
384	    private long parseLongPathParam(Context ctx, String param) {
385	        try {
386	            return Long.parseLong(ctx.pathParam(param));
387	        } catch (NumberFormatException e) {
388	            throw new ApiException(400, "INVALID_REQUEST", "Invalid " + param);
389	        }
390	    }
391	}

