141	public class ReservationRepository {
142	    private final DataSource dataSource;
143	    private final List<ReservationObserver> observers;
144	
145	    public ReservationRepository(DataSource dataSource, List<ReservationObserver> observers) {
146	        this.dataSource = dataSource;
147	        this.observers = observers;
148	    }
149	
150	    public void save(Reservation reservation) {
151	        if (reservation.getId() == null) {
152	            insert(reservation);
153	        } else {
154	            update(reservation);
155	        }
156	    }
157	
158	    private void insert(Reservation reservation) {
159	        String sql = """
160	            INSERT INTO reservations (
161	                room_number, room_type, guest_name, guest_email, guest_cpf,
162	                check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
163	                status, amount_paid, refund
164	            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
165	            """;
166	
167	        try (Connection conn = dataSource.getConnection();
168	             PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
169	
170	            setReservationParameters(stmt, reservation);
171	
172	            stmt.executeUpdate();
173	
174	            try (ResultSet rs = stmt.getGeneratedKeys()) {
175	                if (rs.next()) {
176	                    reservation.setId(rs.getLong(1));
177	                }
178	            }
179	        } catch (SQLException e) {
180	            throw new RuntimeException("Error saving reservation", e);
181	        }
182	    }
183	
184	    private void update(Reservation reservation) {
185	        String sql = """
186	            UPDATE reservations SET
187	                status = ?, amount_paid = ?, refund = ?
188	            WHERE id = ?
189	            """;
190	
191	        try (Connection conn = dataSource.getConnection();
192	             PreparedStatement stmt = conn.prepareStatement(sql)) {
193	
194	            stmt.setString(1, reservation.getStatus().name());
195	            stmt.setBigDecimal(2, reservation.getAmountPaid());
196	            stmt.setBigDecimal(3, reservation.getRefund());
197	            stmt.setLong(4, reservation.getId());
198	
199	            stmt.executeUpdate();
200	        } catch (SQLException e) {
201	            throw new RuntimeException("Error updating reservation", e);
202	        }
203	    }
204	
205	    private void setReservationParameters(PreparedStatement stmt, Reservation reservation) throws SQLException {
206	        stmt.setString(1, reservation.getRoomNumber());
207	        stmt.setString(2, reservation.getRoomType().name());
208	        stmt.setString(3, reservation.getGuestName());
209	        stmt.setString(4, reservation.getGuestEmail());
210	        stmt.setString(5, reservation.getGuestCpf());
211	        stmt.setDate(6, Date.valueOf(reservation.getCheckIn()));
212	        stmt.setDate(7, Date.valueOf(reservation.getCheckOut()));
213	        stmt.setInt(8, reservation.getGuests());
214	        stmt.setString(9, reservation.getRatePlan().name());
215	        stmt.setInt(10, reservation.getNights());
216	        stmt.setBigDecimal(11, reservation.getSubtotal());
217	        stmt.setBigDecimal(12, reservation.getDiscount());
218	        stmt.setBigDecimal(13, reservation.getTotal());
219	        stmt.setString(14, reservation.getStatus().name());
220	        stmt.setBigDecimal(15, reservation.getAmountPaid());
221	        stmt.setBigDecimal(16, reservation.getRefund());
222	    }
