224	    public Optional<Reservation> findById(Long id) {
225	        String sql = """
226	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf,
227	                   check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
228	                   status, amount_paid, refund
229	            FROM reservations
230	            WHERE id = ?
231	            """;
232	
233	        try (Connection conn = dataSource.getConnection();
234	             PreparedStatement stmt = conn.prepareStatement(sql)) {
235	
236	            stmt.setLong(1, id);
237	
238	            try (ResultSet rs = stmt.executeQuery()) {
239	                if (rs.next()) {
240	                    return Optional.of(mapReservation(rs));
241	                }
242	            }
243	        } catch (SQLException e) {
244	            throw new RuntimeException("Error finding reservation", e);
245	        }
246	
247	        return Optional.empty();
248	    }
