250	    public List<Reservation> findByRoomAndDateRange(String roomNumber, LocalDate checkIn, LocalDate checkOut) {
251	        String sql = """
252	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf,
253	                   check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
254	                   status, amount_paid, refund
255	            FROM reservations
256	            WHERE room_number = ?
257	              AND status != 'CANCELLED'
258	              AND check_in < ?
259	              AND check_out > ?
260	            """;
261	
262	        List<Reservation> reservations = new ArrayList<>();
263	
264	        try (Connection conn = dataSource.getConnection();
265	             PreparedStatement stmt = conn.prepareStatement(sql)) {
266	
267	            stmt.setString(1, roomNumber);
268	            stmt.setDate(2, Date.valueOf(checkOut));
269	            stmt.setDate(3, Date.valueOf(checkIn));
270	
271	            try (ResultSet rs = stmt.executeQuery()) {
272	                while (rs.next()) {
273	                    reservations.add(mapReservation(rs));
274	                }
275	            }
276	        } catch (SQLException e) {
277	            throw new RuntimeException("Error finding reservations", e);
278	        }
279	
280	        return reservations;
281	    }
