283	    public List<Reservation> findPaidReservationsForNight(LocalDate night) {
284	        String sql = """
285	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf,
286	                   check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
287	                   status, amount_paid, refund
288	            FROM reservations
289	            WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
290	              AND check_in <= ?
291	              AND check_out > ?
292	            ORDER BY room_number
293	            """;
294	
295	        List<Reservation> reservations = new ArrayList<>();
296	
297	        try (Connection conn = dataSource.getConnection();
298	             PreparedStatement stmt = conn.prepareStatement(sql)) {
299	
300	            stmt.setDate(1, Date.valueOf(night));
301	            stmt.setDate(2, Date.valueOf(night));
302	
303	            try (ResultSet rs = stmt.executeQuery()) {
304	                while (rs.next()) {
305	                    reservations.add(mapReservation(rs));
306	                }
307	            }
308	        } catch (SQLException e) {
309	            throw new RuntimeException("Error finding reservations for night", e);
310	        }
311	
312	        return reservations;
313	    }
314	
315	    public List<Reservation> findReservationsForRevenueReport(int year, int month) {
316	        String sql = """
317	            SELECT id, room_number, room_type, guest_name, guest_email, guest_cpf,
318	                   check_in, check_out, guests, rate_plan, nights, subtotal, discount, total,
319	                   status, amount_paid, refund
320	            FROM reservations
321	            WHERE EXTRACT(YEAR FROM check_in) = ?
322	              AND EXTRACT(MONTH FROM check_in) = ?
323	              AND amount_paid - COALESCE(refund, 0) > 0
324	            ORDER BY check_in, id
325	            """;
326	
327	        List<Reservation> reservations = new ArrayList<>();
328	
329	        try (Connection conn = dataSource.getConnection();
330	             PreparedStatement stmt = conn.prepareStatement(sql)) {
331	
332	            stmt.setInt(1, year);
333	            stmt.setInt(2, month);
334	
335	            try (ResultSet rs = stmt.executeQuery()) {
336	                while (rs.next()) {
337	                    reservations.add(mapReservation(rs));
338	                }
339	            }
340	        } catch (SQLException e) {
341	            throw new RuntimeException("Error finding reservations for revenue report", e);
342	        }
343	
344	        return reservations;
345	    }
346	
347	    private Reservation mapReservation(ResultSet rs) throws SQLException {
348	        Reservation reservation = new Reservation(
349	            rs.getString("room_number"),
350	            RoomType.valueOf(rs.getString("room_type")),
351	            rs.getString("guest_name"),
352	            rs.getString("guest_email"),
353	            rs.getString("guest_cpf"),
354	            rs.getDate("check_in").toLocalDate(),
355	            rs.getDate("check_out").toLocalDate(),
356	            rs.getInt("guests"),
357	            RatePlan.valueOf(rs.getString("rate_plan"))
358	        );
359	
360	        reservation.setId(rs.getLong("id"));
361	        reservation.setStatus(ReservationStatus.valueOf(rs.getString("status")));
362	        reservation.setAmountPaid(rs.getBigDecimal("amount_paid"));
363	
364	        BigDecimal refund = rs.getBigDecimal("refund");
365	        reservation.setRefund(refund);
366	
367	        for (ReservationObserver observer : observers) {
368	            reservation.addObserver(observer);
369	        }
370	
371	        return reservation;
372	    }
373	}
