  6	import java.math.BigDecimal;
  7	import java.math.RoundingMode;
  8	import java.time.LocalDate;
  9	import java.time.temporal.ChronoUnit;
 10	import java.util.ArrayList;
 11	import java.util.List;
 12	
 13	public class Reservation {
 14	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
 15	
 16	    private Long id;
 17	    private final String roomNumber;
 18	    private final RoomType roomType;
 19	    private final String guestName;
 20	    private final String guestEmail;
 21	    private final String guestCpf;
 22	    private final LocalDate checkIn;
 23	    private final LocalDate checkOut;
 24	    private final int guests;
 25	    private final RatePlan ratePlan;
 26	    private final int nights;
 27	    private final BigDecimal subtotal;
 28	    private final BigDecimal discount;
 29	    private final BigDecimal total;
 30	
 31	    private ReservationStatus status;
 32	    private BigDecimal amountPaid;
 33	    private BigDecimal refund;
 34	
 35	    private final List<ReservationObserver> observers = new ArrayList<>();
 36	
 37	    public Reservation(String roomNumber, RoomType roomType, String guestName, String guestEmail,
 38	                      String guestCpf, LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
 39	        this.roomNumber = roomNumber;
 40	        this.roomType = roomType;
 41	        this.guestName = guestName;
 42	        this.guestEmail = guestEmail;
 43	        this.guestCpf = guestCpf;
 44	        this.checkIn = checkIn;
 45	        this.checkOut = checkOut;
 46	        this.guests = guests;
 47	        this.ratePlan = ratePlan;
 48	        this.status = ReservationStatus.PENDING;
 49	        this.amountPaid = BigDecimal.ZERO;
 50	
 51	        this.nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
 52	        this.subtotal = calculateSubtotal();
 53	        this.discount = calculateDiscount();
 54	        this.total = subtotal.subtract(discount);
 55	    }
 56	
 57	    private BigDecimal calculateSubtotal() {
 58	        BigDecimal sum = BigDecimal.ZERO;
 59	        LocalDate currentDate = checkIn;
 60	
 61	        while (currentDate.isBefore(checkOut)) {
 62	            BigDecimal nightRate = roomType.getNightlyRate();
 63	
 64	            if (SeasonCalculator.isHighSeason(currentDate)) {
 65	                nightRate = nightRate.multiply(HIGH_SEASON_MULTIPLIER)
 66	                    .setScale(2, RoundingMode.HALF_EVEN);
 67	            }
 68	
 69	            sum = sum.add(nightRate);
 70	            currentDate = currentDate.plusDays(1);
 71	        }
 72	
 73	        return sum.setScale(2, RoundingMode.HALF_EVEN);
 74	    }
 75	
 76	    private BigDecimal calculateDiscount() {
 77	        if (ratePlan.getDiscountRate().compareTo(BigDecimal.ZERO) == 0) {
 78	            return BigDecimal.ZERO;
 79	        }
 80	
 81	        return subtotal.multiply(ratePlan.getDiscountRate())
 82	            .setScale(2, RoundingMode.HALF_EVEN);
 83	    }
 84	
 85	    public void addObserver(ReservationObserver observer) {
 86	        observers.add(observer);
 87	    }
 88	
 89	    public void confirm() {
 90	        if (status != ReservationStatus.PENDING) {
 91	            throw new IllegalStateException("Only pending reservations can be confirmed");
 92	        }
 93	
 94	        ReservationStatus previousStatus = this.status;
 95	        this.status = ReservationStatus.CONFIRMED;
 96	        this.amountPaid = total;
 97	
 98	        notifyConfirmed();
 99	    }
100	
101	    public void checkIn() {
102	        if (status != ReservationStatus.CONFIRMED) {
103	            throw new IllegalStateException("Only confirmed reservations can be checked in");
104	        }
105	        this.status = ReservationStatus.CHECKED_IN;
106	    }
107	
108	    public void checkOut() {
109	        if (status != ReservationStatus.CHECKED_IN) {
110	            throw new IllegalStateException("Only checked-in reservations can be checked out");
111	        }
112	        this.status = ReservationStatus.CHECKED_OUT;
113	    }
114	
115	    public void cancel() {
116	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
117	            throw new IllegalStateException("Only pending or confirmed reservations can be cancelled");
118	        }
119	
120	        boolean wasConfirmed = (status == ReservationStatus.CONFIRMED);
121	
122	        if (wasConfirmed && ratePlan.isRefundable()) {
123	            this.refund = amountPaid;
124	        } else {
125	            this.refund = BigDecimal.ZERO;
126	        }
127	
128	        this.status = ReservationStatus.CANCELLED;
129	
130	        notifyCancelled(wasConfirmed);
131	    }
132	
133	    private void notifyConfirmed() {
134	        for (ReservationObserver observer : observers) {
135	            observer.onReservationConfirmed(this);
136	        }
137	    }
138	
139	    private void notifyCancelled(boolean wasConfirmed) {
140	        for (ReservationObserver observer : observers) {
141	            observer.onReservationCancelled(this, wasConfirmed);
142	        }
143	    }
