339	    public static boolean isHighSeason(LocalDate date) {
340	        Month month = date.getMonth();
341	        int day = date.getDayOfMonth();
342	
343	        if (month == Month.JULY) {
344	            return true;
345	        }
346	
347	        if (month == Month.DECEMBER && day >= 15) {
348	            return true;
349	        }
350	
351	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
352	            return true;
353	        }
354	
355	        return false;
356	    }
357	}
