 12	class ReservationObserverTest {
 13	
 14	    static class TestObserver implements ReservationObserver {
 15	        final List<String> events = new ArrayList<>();
 16	
 17	        @Override
 18	        public void onReservationConfirmed(Reservation reservation) {
 19	            events.add("confirmed:" + reservation.getId());
 20	        }
 21	
 22	        @Override
 23	        public void onReservationCancelled(Reservation reservation, boolean wasConfirmed) {
 24	            events.add("cancelled:" + reservation.getId() + ":" + wasConfirmed);
 25	        }
 26	    }
 27	
 28	    @Test
 29	    void shouldNotifyObserversOnConfirmation() {
 30	        TestObserver observer1 = new TestObserver();
 31	        TestObserver observer2 = new TestObserver();
 32	
 33	        Reservation reservation = new Reservation(
 34	            "101",
 35	            RoomType.STANDARD,
 36	            "João Silva",
 37	            "joao@example.com",
 38	            "12345678901",
 39	            LocalDate.of(2027, 7, 10),
