 43	        );
 44	
 45	        reservation.setId(1L);
 46	        reservation.addObserver(observer1);
 47	        reservation.addObserver(observer2);
 48	
 49	        reservation.confirm();
 50	
 51	        assertThat(observer1.events).containsExactly("confirmed:1");
 52	        assertThat(observer2.events).containsExactly("confirmed:1");
 53	    }
